// Reads the tutor's server-sent events. Resolves with the full text, or {error} if the server reported one mid-stream.
async function readTutorStream(resp,onDelta,onMeta){
 const reader=resp.body.getReader(),decoder=new TextDecoder();let buf='',text='',error=null;
 for(;;){
  const {value,done}=await reader.read();if(done)break;
  buf+=decoder.decode(value,{stream:true});
  let i;while((i=buf.indexOf('\n\n'))>=0){
   const block=buf.slice(0,i);buf=buf.slice(i+2);
   const name=/^event: (.+)$/m.exec(block)?.[1],raw=/^data: (.+)$/m.exec(block)?.[1];if(!name||!raw)continue;
   let data;try{data=JSON.parse(raw);}catch{continue;}
   if(name==='meta')onMeta(data);else if(name==='delta'&&typeof data.text==='string'){text+=data.text;onDelta(data.text);}else if(name==='error')error=data.error||'Se interrumpió la respuesta.';
  }
 }
 return error?{error}:{text};
}
